scripts.script:
// Raw observations per group (Box-Muller Gaussian; Math.random is seeded by
// the sample template).
function sample(mean, sd, n) {
  var points = []
  for (var k = 0; k < n; k++) {
    var u1 = Math.random(),
      u2 = Math.random()
    var g = Math.sqrt(-2 * Math.log(u1)) * Math.cos(2 * Math.PI * u2)
    points.push(Math.round((mean + g * sd) * 10) / 10)
  }
  return points
}

// Each layout is a complete plotOptions.violin spec, so switching between
// them never leaves a leaf from the previous layout behind. Hidden layers
// hand their lane back to the cloud automatically.
var RAINCLOUD_LAYOUTS = {
  classic: {
    side: 'right',
    box: { show: true },
    points: { show: true, position: 'left' },
  },
  'cloud-rain': {
    side: 'right',
    box: { show: false },
    points: { show: true, position: 'left' },
  },
  'cloud-box': {
    side: 'right',
    box: { show: true },
    points: { show: false, position: 'left' },
  },
  overlay: {
    side: 'both',
    box: { show: true },
    points: { show: true, position: 'center', constrainToViolin: true },
  },
}

html:
Layout: Classic raincloud Cloud + rain Cloud + box Violin + box overlay
{{ charts[0] }}
Every raincloud layer is its own switch on plotOptions.violin: side cuts the density to a half-violin, box.show toggles the five-number lane, and points.position moves the raw observations into their own lane or back under the density. A hidden layer hands its lane back to the cloud, so Cloud + rain and Cloud + box reflow instead of leaving a gap, and Violin + box overlay (side: 'both') is the classic symmetric violin with the box drawn on its centerline.

chart.options:
chart: {
  id: 'raincloudVariations',
  type: 'raincloud',
  height: 420,
},
colors: ['#14b8a6'],
title: {
  text: 'One distribution chart, four layouts',
  align: 'left',
},
yaxis: {
  title: {
    text: 'Measurement',
  },
},

chart.series:
[
  {
    name: 'Measurement',
    data: [
      { x: 'North', points: sample(52, 9, 160) },
      { x: 'East', points: sample(61, 6, 160) },
      { x: 'South', points: sample(47, 12, 160) },
    ],
  },
]

vanilla-js-script:
// RAINCLOUD_LAYOUTS lives in the shared head script.
var layoutButtons = Array.prototype.slice.call(
  document.querySelectorAll('.controls button[data-layout]')
)

layoutButtons.forEach(function (btn) {
  btn.addEventListener('click', function () {
    layoutButtons.forEach(function (b) { b.classList.remove('active') })
    btn.classList.add('active')
    chart.updateOptions({
      plotOptions: { violin: RAINCLOUD_LAYOUTS[btn.getAttribute('data-layout')] },
    })
  })
})

react-script:
React.useEffect(() => {
  // The react-apexcharts wrapper owns the render, so reach the live instance
  // by its chart.id, then wire the same controls the vanilla build does.
  // (RAINCLOUD_LAYOUTS lives in the shared head script.)
  let chart
  const timer = window.setInterval(() => {
    chart = ApexCharts.getChartByID('raincloudVariations')
    if (!chart) return
    window.clearInterval(timer)

    const buttons = Array.prototype.slice.call(
      document.querySelectorAll('.controls button[data-layout]')
    )
    buttons.forEach((btn) => {
      btn.addEventListener('click', () => {
        buttons.forEach((b) => b.classList.remove('active'))
        btn.classList.add('active')
        chart.updateOptions({
          plotOptions: { violin: RAINCLOUD_LAYOUTS[btn.getAttribute('data-layout')] },
        })
      })
    })
  }, 50)

  return () => window.clearInterval(timer)
}, [])

vue-script:
mounted: function () {
  // The vue-apexcharts wrapper owns the render, so reach the live instance
  // by its chart.id, then wire the same controls the vanilla build does.
  // (RAINCLOUD_LAYOUTS lives in the shared head script.)
  var me = this
  me.raincloudTimer = window.setInterval(function () {
    var chart = ApexCharts.getChartByID('raincloudVariations')
    if (!chart) return
    window.clearInterval(me.raincloudTimer)

    var buttons = Array.prototype.slice.call(
      document.querySelectorAll('.controls button[data-layout]')
    )
    buttons.forEach(function (btn) {
      btn.addEventListener('click', function () {
        buttons.forEach(function (b) { b.classList.remove('active') })
        btn.classList.add('active')
        chart.updateOptions({
          plotOptions: { violin: RAINCLOUD_LAYOUTS[btn.getAttribute('data-layout')] },
        })
      })
    })
  }, 50)
},
beforeDestroy: function () {
  window.clearInterval(this.raincloudTimer)
},
